package com.jnapanam.sportszone.content.controller;import com.jnapanam.sportszone.content.dto.*;import com.jnapanam.sportszone.content.model.InquiryStatus;import com.jnapanam.sportszone.content.service.ContentService;import jakarta.validation.Valid;import java.util.*;import org.springframework.http.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;
@RestController@RequestMapping("/api/v1/admin/content")@PreAuthorize("hasAnyRole('SUPER_ADMIN','ADMIN','OPERATIONS')")public class AdminContentController{private final ContentService service;public AdminContentController(ContentService s){service=s;}@GetMapping("/events")public List<EventResponse>events(){return service.allEvents();}@PostMapping("/events")@ResponseStatus(HttpStatus.CREATED)public EventResponse createEvent(@Valid@RequestBody EventRequest r){return service.createEvent(r);}@PutMapping("/events/{id}")public EventResponse updateEvent(@PathVariable UUID id,@Valid@RequestBody EventRequest r){return service.updateEvent(id,r);}@PatchMapping("/events/{id}/status")public EventResponse eventStatus(@PathVariable UUID id,@Valid@RequestBody ContentStatusRequest r){return service.eventStatus(id,r);}@GetMapping("/announcements")public List<AnnouncementResponse>announcements(){return service.allAnnouncements();}@PostMapping("/announcements")@ResponseStatus(HttpStatus.CREATED)public AnnouncementResponse createAnnouncement(@Valid@RequestBody AnnouncementRequest r){return service.createAnnouncement(r);}@PatchMapping("/announcements/{id}/status")public AnnouncementResponse announcementStatus(@PathVariable UUID id,@Valid@RequestBody ContentStatusRequest r){return service.announcementStatus(id,r);}@GetMapping("/gallery")public List<GalleryResponse>gallery(){return service.allGallery();}@PostMapping("/gallery")@ResponseStatus(HttpStatus.CREATED)public GalleryResponse createGallery(@Valid@RequestBody GalleryRequest r){return service.createGallery(r);}@GetMapping("/pages")public List<PageResponse>pages(){return service.allPages();}@PutMapping("/pages")public PageResponse savePage(@Valid@RequestBody PageRequest r){return service.savePage(r);}@GetMapping("/inquiries")public List<ContactResponse>inquiries(@RequestParam(required=false)InquiryStatus status){return service.inquiries(status);}@PatchMapping("/inquiries/{id}/status")public ContactResponse inquiryStatus(@PathVariable UUID id,@Valid@RequestBody InquiryStatusRequest r){return service.inquiryStatus(id,r);}}
